<script setup lang="ts">
import {ref,watch} from 'vue';import {http} from '../../api/http';import {day} from '../../utils/dates';import type {Row} from '../../shared/records'
const props=defineProps<{site?:number;meal:string}>(),from=ref(day(-14)),to=ref(day(-1)),data=ref<Row|null>(null),error=ref(''),pending=ref(false);let generation=0
async function run(){if(!props.site)return;const g=++generation;pending.value=true;error.value='';data.value=null;try{const result=await http.get<never,Row>(`/sites/${props.site}/forecast-backtest`,{params:{dateFrom:from.value,dateTo:to.value,mealType:props.meal}});if(g===generation)data.value=result}catch(e){if(g===generation)error.value=(e as Error).message}finally{if(g===generation)pending.value=false}}
watch(()=>[props.site,props.meal],()=>{generation++;pending.value=false;data.value=null;error.value=''})
const labels:Row={EVALUATED:'已比较',MISSING_ACTUAL:'实际人数缺失',INSUFFICIENT:'训练样本不足',CLOSED:'停餐，排除'}
</script><template><section class="content-card" style="margin-top:24px"><h2>历史回测与算法比较</h2><p>选择今天之前的历史日期，逐日只使用此前 56 天已登记的实际人数。MAE 为平均绝对误差，RMSE 更重视较大的偏差，单位均为人。样本少时不应据此判断实际效果。</p><div class="toolbar"><label for="backtest-from">回测开始日期</label><el-input id="backtest-from" v-model="from" type="date"/><label for="backtest-to">回测结束日期</label><el-input id="backtest-to" v-model="to" type="date"/><el-button type="primary" :loading="pending" @click="run">运行历史回测</el-button></div><el-alert v-if="error" :title="error" type="error" :closable="false"/><template v-if="data"><p>{{data.notice}}</p><el-table :data="data.reports"><el-table-column prop="algorithm" label="算法标识" min-width="240"/><el-table-column prop="evaluated" label="有效比较天数"/><el-table-column label="MAE"><template #default="{row}">{{row.mae==null?'无有效样本':Number(row.mae).toFixed(2)}}</template></el-table-column><el-table-column label="RMSE"><template #default="{row}">{{row.rmse==null?'无有效样本':Number(row.rmse).toFixed(2)}}</template></el-table-column><el-table-column prop="insufficient" label="样本不足天数"/><el-table-column prop="missing" label="缺失天数"/><el-table-column prop="closed" label="停餐天数"/></el-table><el-collapse><el-collapse-item v-for="report in data.reports" :key="report.algorithm" :title="report.algorithm+' · 逐日结果与训练样本'"><el-table :data="report.observations"><el-table-column prop="date" label="目标日期"/><el-table-column prop="actual" label="实际人数"/><el-table-column prop="predicted" label="预测人数"/><el-table-column label="状态"><template #default="{row}">{{labels[row.status]}}</template></el-table-column><el-table-column label="使用的历史日期" min-width="250"><template #default="{row}">{{row.sampleDates.join('、')||'无'}}</template></el-table-column></el-table></el-collapse-item></el-collapse></template></section></template>
